<?php declare(strict_types=1);session_start();if(empty($_SESSION['user'])||($_SESSION['user']['rol']??'')!=='superadmin'){http_response_code(403);exit('Acceso no autorizado.');}$config=require __DIR__.'/config.php';function h(string $v):string{return htmlspecialchars($v,ENT_QUOTES,'UTF-8');}try{$pdo=new PDO(sprintf('mysql:host=%s;port=%d;dbname=%s;charset=utf8mb4',$config['host'],$config['port'],$config['database']),$config['user'],$config['password'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);$cats=$pdo->query('SELECT id,nombre,slug,descripcion,orden,estado FROM galeria_categorias ORDER BY orden,nombre')->fetchAll();$stores=$pdo->query('SELECT id,nombre,galeria_categoria_id FROM tiendas ORDER BY nombre')->fetchAll();}catch(Throwable $e){http_response_code(500);exit('Ejecuta primero la migración de categorías generales en phpMyAdmin.');}?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Categorías de Galería</title><style>body{font-family:system-ui;background:#f6f3ee;margin:0}main{max-width:950px;margin:auto;padding:30px 20px}.card{background:#fff;padding:24px;border-radius:16px;margin:16px 0}label{display:block;margin:9px 0 4px}input,select,textarea{box-sizing:border-box;width:100%;padding:9px;border:1px solid #ccc;border-radius:7px}button{margin-top:12px;padding:10px 16px;background:#886c42;color:#fff;border:0;border-radius:7px}a{color:#886c42}table{width:100%;border-collapse:collapse}th,td{text-align:left;padding:10px 7px;border-bottom:1px solid #eee}</style></head><body><main><p><a href="dashboard-admin.php">← Dashboard</a></p><section class="card"><h1>Categorías de la Galería</h1><form method="post" action="galeria-categoria-guardar.php"><label>Nombre</label><input name="nombre" required maxlength="120"><label>Descripción</label><textarea name="descripcion"></textarea><label>Orden</label><input type="number" name="orden" value="0" min="0"><button>Crear categoría</button></form></section><section class="card"><h2>Asignar tiendas</h2><form method="post" action="tienda-galeria-categoria.php"><label>Tienda</label><select name="tienda_id" required><?php foreach($stores as $s):?><option value="<?=$s['id']?>"><?=h($s['nombre'])?></option><?php endforeach;?></select><label>Categoría general</label><select name="categoria_id" required><?php foreach($cats as $c):?><option value="<?=$c['id']?>"><?=h($c['nombre'])?></option><?php endforeach;?></select><button>Asignar tienda</button></form></section><section class="card"><h2>Categorías y tiendas</h2><table><thead><tr><th>Categoría</th><th>Estado</th><th>Tiendas</th></tr></thead><tbody><?php foreach($cats as $c):?><tr><td><?=h($c['nombre'])?></td><td><?=h($c['estado'])?></td><td><?php $names=[];foreach($stores as $s){if((int)$s['galeria_categoria_id']===(int)$c['id'])$names[]=$s['nombre'];}echo h(implode(', ',$names)?:'Sin tiendas');?></td></tr><?php endforeach;?></tbody></table></section></main></body></html>
